+use camcraft_app::mcp::Server;
+use serde_json::{Value, json};
+
+struct Client {
+    server: Server,
+    id: i64,
+}
+
+impl Client {
+    fn new() -> Self {
+        Self {
+            server: Server::new(),
+            id: 1,
+        }
+    }
+
+    fn request(&mut self, method: &str, params: Value) -> Value {
+        let id = self.id;
+        self.id += 1;
+        let reply = self
+            .server
+            .handle(&json!({
+                "jsonrpc": "2.0",
+                "id": id,
+                "method": method,
+                "params": params
+            }))
+            .expect("MCP response");
+        assert_eq!(reply["id"], json!(id));
+        reply
+    }
+
+    fn call(&mut self, tool: &str, args: Value) -> (bool, Value) {
+        let reply = self.request("tools/call", json!({ "name": tool, "arguments": args }));
+        let result = &reply["result"];
+        let is_error = result["isError"] == json!(true);
+        let body = if is_error {
+            result["content"][0]["text"].clone()
+        } else {
+            result["structuredContent"].clone()
+        };
+        (is_error, body)
+    }
+
+    fn ok(&mut self, tool: &str, args: Value) -> Value {
+        let (error, body) = self.call(tool, args);
+        assert!(!error, "{tool} refused: {body}");
+        body
+    }
+}
+
