+fn rect(x0: f64, y0: f64, x1: f64, y1: f64) -> Region {
+    Region::new(vec![
+        Loop::new(vec![
+            Point2::new(x0, y0),
+            Point2::new(x1, y0),
+            Point2::new(x1, y1),
+            Point2::new(x0, y1),
+        ])
+        .expect("loop"),
+    ])
+    .expect("region")
+}
+
+fn params(minimum_cone_radius: f64, side: Side) -> ChamferParams {
+    ChamferParams {
+        width: 1.0,
+        angle_deg: 45.0,
+        minimum_cone_radius,
+        clearance_z: 25.0,
+        retract_z: None,
+        top_z: 20.0,
+        feed: 500.0,
+        plunge_feed: 100.0,
+        climb: true,
+        inside: side == Side::Inside,
+    }
+}
+
+fn refusal<T>(result: Result<T, GenError>) -> String {
+    match result {
+        Ok(_) => panic!("the minimum-radius door should refuse"),
+        Err(error) => error.to_string(),
+    }
+}
